import {avatarPresets,renderAvatar} from './avatar-presets.mjs';
const $=s=>document.querySelector(s),form=$('#profileForm'),status=$('#pageStatus');
const colours=['stone','forest','ocean','sunset','plum','gold'];
const privacyLabels={nickname:'Nickname',country:'Country',collection:'Owned collection',level:'Collector level',badges:'Badges',firstName:'First name',lastName:'Last name'};
let profile=null,catalog=new Map(),assets={},dirty=false,uploading=false,collectionItems=[],collectionTarget=null;
let cataloguePromise;
function loadCatalogue(){return cataloguePromise??=Promise.all([fetch('catalog.json').then(r=>r.json()),fetch('assets.json').then(r=>r.json())]).then(([pieces,images])=>{catalog=new Map(pieces.map(p=>[p.id,p]));assets=images;});}
const collector=new URLSearchParams(location.search).get('collector');
async function request(path,options={}){const r=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await r.json();if(!r.ok){const e=Error(data.error||'Could not complete this request.');e.status=r.status;throw e}return data}
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function countryName(code){try{return code?new Intl.DisplayNames(['en'],{type:'region'}).of(code):''}catch{return code||''}}
function paintHero(p,isPublic=false){$('#profileHero').hidden=false;const nickname=isPublic?p.nickname:p.display_name;$('#profileName').textContent=nickname||(isPublic?'Edge Collector':'Your collector profile');const avatar=$('#profileAvatar');avatar.className='avatar '+(colours.includes(p.avatar)?p.avatar:'stone');renderAvatar(avatar,p,{name:nickname||'',publicId:isPublic?collector:null});avatar.hidden=false;const realName=isPublic?[p.firstName,p.lastName].filter(Boolean).join(' '):'';$('#profileRealName').textContent=realName;$('#profileRealName').hidden=!realName;$('#profileLevel').hidden=p.level===undefined;$('#profileLevel').textContent='Level '+(p.level??0);$('#profileCountry').textContent=countryName(p.country);$('#visibilityLabel').textContent=isPublic?'':p.public_sharing?'Public profile':'Private profile';const badges=$('#profileBadges');badges.replaceChildren();for(const b of p.badges||[])badges.append(el('span',(b.kind==='official'?'✓ ':'')+b.label,'badge '+b.kind));}
function collectionCards(items,target){target.replaceChildren();if(!items.length){target.append(el('p','No owned pieces yet.'));return}for(const item of items){const p=catalog.get(item.productId),card=el('article',undefined,'collection-card'),img=new Image();img.alt='';img.loading='lazy';img.src=assets[item.productId]?.src||p?.img||'';card.append(img,el('h3',p?.name||'Edge Sculpture'),el('p',item.quantity+' owned '+(item.quantity===1?'copy':'copies')));target.append(card)}}
function fillProfile(p){profile=p;paintHero(p);for(const [name,value] of Object.entries({nickname:p.display_name,firstName:p.first_name,lastName:p.last_name,email:p.email,phone:p.phone,country:p.country}))form.elements[name].value=value||'';form.elements.avatar.value=p.avatar;form.elements.avatarStyle.value=p.avatar_style||'initials';$('#photoPreset').hidden=!p.avatar_version;form.elements.publicSharing.checked=p.public_sharing;for(const key of Object.keys(privacyLabels))form.elements['privacy_'+key].checked=p.privacy[key]===true;$('#privacyFields').disabled=!p.public_sharing;$('#manageEmail').href=p.accountUrl||$('#manageEmail').href;$('#adminTab').hidden=!p.isAdmin;dirty=false;}
function selectPanel(name){for(const button of document.querySelectorAll('[data-panel]'))button.setAttribute('aria-pressed',String(button.dataset.panel===name));for(const section of document.querySelectorAll('[data-section]'))section.hidden=section.dataset.section!==name;form.hidden=!['details','privacy'].includes(name);if(name==='admin')loadAdmin();if(name==='collection'){loadCatalogue().then(()=>collectionCards(collectionItems,$('#collectionList'))).catch(()=>{$('#collectionList').textContent='Could not load collection images. Please reload.'})}}
for(const button of document.querySelectorAll('[data-panel]'))button.onclick=()=>selectPanel(button.dataset.panel);
for(const c of colours){const label=el('label'),input=el('input');input.type='radio';input.name='avatar';input.value=c;input.setAttribute('aria-label',c+' profile colour');label.append(input,el('span',undefined,'swatch '+c));$('#avatarOptions').append(label)}

for(const p of [{id:'initials',label:'Initials'},...avatarPresets,{id:'photo',label:'My photo'}]){
 const label=el('label',undefined,'preset-option'),input=el('input');input.type='radio';input.name='avatarStyle';input.value=p.id;input.setAttribute('aria-label',p.label+' profile picture');
 const tile=el('span',undefined,'preset-tile');if(p.id==='initials')tile.textContent='Aa';else if(p.id==='photo'){tile.textContent='Photo';label.id='photoPreset';label.hidden=true}else{const img=new Image();img.src='avatars/'+p.id+'.svg';img.alt='';tile.append(img)}
 label.append(input,tile,el('span',p.label));$('#presetOptions').append(label);
}
$('#avatarFile').onchange=async e=>{
 const file=e.target.files?.[0];if(!file)return;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10000000){$('#avatarStatus').textContent='Choose a JPG, PNG or WebP photo smaller than 10 MB.';return}
 uploading=true;$('#saveProfile').disabled=true;$('#avatarStatus').textContent='Preparing photo…';
 try{
  const image=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=canvas.height=512;const context=canvas.getContext('2d');const side=Math.min(image.width,image.height);context.drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,512,512);image.close();
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw Error('Could not prepare this photo.');
  const result=await request('avatar',{method:'POST',headers:{'Content-Type':'image/jpeg','X-Profile-Revision':String(profile.profile_revision)},body:blob});
  Object.assign(profile,result);$('#photoPreset').hidden=false;form.elements.avatarStyle.value='photo';renderAvatar($('#profileAvatar'),profile,{name:form.elements.nickname.value});$('#avatarStatus').textContent='Photo saved. Other changes still need Save changes.';
 }catch(error){$('#avatarStatus').textContent=error.message}finally{uploading=false;$('#saveProfile').disabled=false;e.target.value=''}
};

for(const [key,label] of Object.entries(privacyLabels)){const row=el('label',undefined,'toggle-row'),input=el('input');input.type='checkbox';input.name='privacy_'+key;row.append(el('span',label),input);$('#privacyOptions').append(row)}
// ISO 3166-1 alpha-2 codes; labels are localised by the browser.
const codes='AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW'.split(' ');
for(const code of codes.sort((a,b)=>countryName(a).localeCompare(countryName(b))))form.elements.country.add(new Option(countryName(code),code));
form.elements.publicSharing.onchange=()=>{if(form.elements.publicSharing.checked)for(const key of Object.keys(privacyLabels))form.elements['privacy_'+key].checked=true;};
form.oninput=e=>{if(e.target.type==='file')return;dirty=true;$('#saveMessage').textContent='Unsaved changes';$('#privacyFields').disabled=!form.elements.publicSharing.checked;const avatar=$('#profileAvatar');avatar.className='avatar '+form.elements.avatar.value;renderAvatar(avatar,{...profile,avatar_style:form.elements.avatarStyle.value},{name:form.elements.nickname.value});};
form.onsubmit=async e=>{e.preventDefault();if(uploading)return;const button=$('#saveProfile');button.disabled=true;$('#saveMessage').textContent='Saving…';try{const p={revision:profile.profile_revision};for(const name of ['nickname','firstName','lastName','phone','country','avatar','avatarStyle'])p[name]=form.elements[name].value;p.publicSharing=form.elements.publicSharing.checked;p.privacy=Object.fromEntries(Object.keys(privacyLabels).map(k=>[k,form.elements['privacy_'+k].checked]));const saved=await request('profile',{method:'PUT',body:JSON.stringify(p)});fillProfile({...saved,accountUrl:profile.accountUrl});$('#saveMessage').textContent='Profile saved.';}catch(error){$('#saveMessage').textContent=error.message;if(error.status===401){const link=el('a',' Sign in again');link.href='/api/auth/login';$('#saveMessage').append(link)}}finally{button.disabled=false}};
function publicLink(){return location.origin+'/profile.html?collector='+profile.id}
$('#previewPublic').onclick=()=>{if(!profile.public_sharing){$('#privacyMessage').textContent='Save your profile as public before previewing it.';return}window.open(publicLink(),'_blank','noopener')};
$('#copyProfile').onclick=async()=>{if(!profile.public_sharing){$('#privacyMessage').textContent='Your profile is private. Enable public visibility and save before sharing.';return}try{await navigator.clipboard.writeText(publicLink());$('#privacyMessage').textContent=dirty?'Link copied. Unsaved changes are not included.':'Profile link copied.'}catch{$('#privacyMessage').textContent=publicLink()}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
async function loadAdmin(){try{const data=await request('admin'),select=$('#badgeForm').elements.ownerId;select.replaceChildren();for(const p of data.users)select.add(new Option((p.display_name||'Collector')+' · Level '+p.level+(p.official?' · Official':'')+' · '+p.id.slice(0,8),p.id));const list=$('#auditList');list.replaceChildren();for(const a of data.events){const row=el('article',undefined,'audit-event');row.append(el('strong',a.action),el('p',new Date(a.created_at).toLocaleString()+' · Collector '+(a.owner_id||'system')),el('p','Actor: '+(a.actor_id||'identity / system')));if(a.reason)row.append(el('p',a.reason));row.append(el('p','Changed: '+Object.keys(a.changes).join(', ')));const details=el('details');details.append(el('summary','View change details'),el('pre',JSON.stringify(a.changes,null,2)));row.append(details);list.append(row)}}catch(e){$('#adminStatus').textContent=e.message}}
$('#badgeForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await request('admin/badge',{method:'POST',body:JSON.stringify({ownerId:f.elements.ownerId.value,active:f.elements.active.value==='true',reason:f.elements.reason.value})});$('#adminStatus').textContent='Badge updated and recorded in the audit log.';f.elements.reason.value='';await loadAdmin();const p=await request('profile');fillProfile(p);}catch(e){$('#adminStatus').textContent=e.message}finally{b.disabled=false}};
async function start(){
 if(collector){const p=await request('profiles/'+encodeURIComponent(collector));paintHero(p,true);document.title=(p.nickname||'Collector')+' · Edge Shelf';status.textContent='';if(p.collection){$('#publicCollection').hidden=false;$('#publicCollectionList').textContent='Loading collection…';await loadCatalogue();collectionCards(p.collection,$('#publicCollectionList'))}return}
 const {profile:p,state}=await request('bootstrap');fillProfile(p);form.hidden=false;$('#profileNav').hidden=false;status.textContent='';
 const quantities=new Map();for(const i of state.items)quantities.set(i.productId,(quantities.get(i.productId)||0)+1);collectionItems=[...quantities].map(([productId,quantity])=>({productId,quantity}));
 const section=new URLSearchParams(location.search).get('section');if(section==='privacy'||section==='collection'||(section==='admin'&&p.isAdmin))selectPanel(section);
}

start().catch(e=>{status.textContent=e.message;if(e.status===401)$('#signedOut').hidden=false});
